import time, numpy as np
from numba import njit
import ot
from ot.lp.emd_wrap import emd_c

@njit
def col_reduce_assign(cost):
    """Greedy column reduction then row reduction. Returns how many assigned and the partial assignment."""
    n = cost.shape[0]
    v = np.empty(n)
    col_of_row = np.full(n, -1, np.int64)
    row_of_col = np.full(n, -1, np.int64)
    # each column to its cheapest row
    for j in range(n):
        best = 1e300
        bi = 0
        for i in range(n):
            cij = cost[i, j]
            if cij < best:
                best = cij
                bi = i
        v[j] = best
        if col_of_row[bi] < 0:
            col_of_row[bi] = j
            row_of_col[j] = bi
    assigned = 0
    for i in range(n):
        if col_of_row[i] >= 0:
            assigned += 1
    # row reduction for free rows onto free cols
    for i in range(n):
        if col_of_row[i] >= 0:
            continue
        best = 1e300
        bj = -1
        for j in range(n):
            if row_of_col[j] >= 0:
                continue
            red = cost[i, j] - v[j]
            if red < best:
                best = red
                bj = j
        if bj >= 0:
            col_of_row[i] = bj
            row_of_col[bj] = i
            assigned += 1
    return assigned

def trial(n, seed):
    np.random.seed(seed)
    M = np.ascontiguousarray(ot.dist(np.random.rand(n,2), np.random.rand(n,2)), np.float64)
    return col_reduce_assign(M)

print("compile", flush=True)
print(trial(20,0))
for n in [200, 600]:
    vals = [trial(n, s) for s in range(8)]
    print(n, vals, "mean", np.mean(vals))
