import time, numpy as np
from numba import njit
import ot

@njit
def knn(cost, k):
    n = cost.shape[0]
    cand = np.empty((n, k), np.int64)
    for i in range(n):
        row = cost[i]
        idx = np.empty(k, np.int64)
        val = np.empty(k)
        tmax = 0
        mv = val[0] if False else row[0]
        for t in range(k):
            idx[t] = t
            val[t] = row[t]
        tmax = 0
        mv = val[0]
        for t in range(1, k):
            if val[t] > mv:
                mv = val[t]
                tmax = t
        for j in range(k, n):
            rj = row[j]
            if rj < mv:
                idx[tmax] = j
                val[tmax] = rj
                tmax = 0
                mv = val[0]
                for t in range(1, k):
                    if val[t] > mv:
                        mv = val[t]
                        tmax = t
        for t in range(k):
            cand[i, t] = idx[t]
    return cand

@njit
def colred(cost):
    n = cost.shape[0]
    v = np.empty(n)
    rowsol = np.full(n, -1, np.int64)
    for j in range(n):
        best = cost[0, j]
        bi = 0
        for i in range(1, n):
            cij = cost[i, j]
            if cij < best:
                best = cij
                bi = i
        v[j] = best
        if rowsol[bi] < 0:
            rowsol[bi] = j
    return v, rowsol

print("compile", flush=True)
M = np.random.rand(30,30)
knn(M, 8); colred(M)
M = np.ascontiguousarray(ot.dist(np.random.rand(600,2), np.random.rand(600,2)))
