#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>
#include <float.h>

/* Min-cost assignment specialized for dense float64 cost matrices.
   Column reduction + successive shortest paths on a k-NN candidate graph,
   falling back to the full graph if the candidate graph is infeasible.
   Returns row->col int64 array.
*/

static void knn_one(const double* row, npy_intp n, int k, npy_intp* idx, double* val) {
    for (int t = 0; t < k; t++) {
        idx[t] = t;
        val[t] = row[t];
    }
    int tmax = 0;
    double mv = val[0];
    for (int t = 1; t < k; t++) {
        if (val[t] > mv) { mv = val[t]; tmax = t; }
    }
    for (npy_intp j = k; j < n; j++) {
        double rj = row[j];
        if (rj < mv) {
            idx[tmax] = j;
            val[tmax] = rj;
            tmax = 0;
            mv = val[0];
            for (int t = 1; t < k; t++) {
                if (val[t] > mv) { mv = val[t]; tmax = t; }
            }
        }
    }
}

/* Dijkstra SSP on candidate graph. Returns 1 on success. */
static int ssp_cand(
    const double* cost, npy_intp n, int k,
    const npy_intp* cand,
    double* u, double* v,
    npy_intp* rowsol, npy_intp* colsol,
    npy_intp* free_rows, npy_intp nf
) {
    const double INF = 1e100;
    double* dist = (double*)malloc(n * sizeof(double));
    npy_intp* pred = (npy_intp*)malloc(n * sizeof(npy_intp));
    unsigned char* seen = (unsigned char*)calloc(n, 1);
    unsigned char* in_active = (unsigned char*)calloc(n, 1);
    npy_intp* active = (npy_intp*)malloc(n * sizeof(npy_intp));
    if (!dist || !pred || !seen || !in_active || !active) return 0;

    for (npy_intp t = 0; t < nf; t++) {
        npy_intp src = free_rows[t];
        for (npy_intp j = 0; j < n; j++) {
            dist[j] = INF;
            seen[j] = 0;
        }
        npy_intp na = 0;
        double us = u[src];
        const double* row = cost + src * n;
        const npy_intp* ci = cand + src * k;
        for (int tt = 0; tt < k; tt++) {
            npy_intp j = ci[tt];
            double d = row[j] - us - v[j];
            if (d < dist[j]) {
                dist[j] = d;
                pred[j] = src;
            }
            if (!in_active[j]) {
                in_active[j] = 1;
                active[na++] = j;
            }
        }
        npy_intp sink = -1;
        double mind = 0.0;
        while (na > 0) {
            double best = INF;
            npy_intp ia = 0;
            for (npy_intp a = 0; a < na; a++) {
                double dj = dist[active[a]];
                if (dj < best) { best = dj; ia = a; }
            }
            npy_intp jmin = active[ia];
            na--;
            active[ia] = active[na];
            in_active[jmin] = 0;
            seen[jmin] = 1;
            npy_intp rmatch = colsol[jmin];
            if (rmatch < 0) { sink = jmin; mind = best; break; }
            double base = best - u[rmatch];
            const double* rcost = cost + rmatch * n;
            const npy_intp* crow = cand + rmatch * k;
            for (int tt = 0; tt < k; tt++) {
                npy_intp j = crow[tt];
                if (!seen[j]) {
                    double nd = base + rcost[j] - v[j];
                    if (nd < dist[j]) {
                        dist[j] = nd;
                        pred[j] = rmatch;
                        if (!in_active[j]) {
                            in_active[j] = 1;
                            active[na++] = j;
                        }
                    }
                }
            }
        }
        for (npy_intp a = 0; a < na; a++) in_active[active[a]] = 0;
        if (sink < 0) {
            free(dist); free(pred); free(seen); free(in_active); free(active);
            return 0;
        }
        u[src] += mind;
        for (npy_intp j = 0; j < n; j++) {
            if (seen[j]) {
                double dlt = dist[j] - mind;
                v[j] += dlt;
                npy_intp r = colsol[j];
                if (r >= 0) u[r] -= dlt;
            }
        }
        npy_intp j = sink;
        while (1) {
            npy_intp r = pred[j];
            npy_intp pj = rowsol[r];
            rowsol[r] = j;
            colsol[j] = r;
            if (r == src) break;
            j = pj;
        }
    }
    free(dist); free(pred); free(seen); free(in_active); free(active);
    return 1;
}

/* Full dense SSP for remaining free rows (correct fallback). */
static void ssp_full(
    const double* cost, npy_intp n,
    double* u, double* v,
    npy_intp* rowsol, npy_intp* colsol,
    npy_intp* free_rows, npy_intp nf
) {
    const double INF = 1e100;
    double* dist = (double*)malloc(n * sizeof(double));
    npy_intp* pred = (npy_intp*)malloc(n * sizeof(npy_intp));
    unsigned char* seen = (unsigned char*)malloc(n);
    for (npy_intp t = 0; t < nf; t++) {
        npy_intp src = free_rows[t];
        double us = u[src];
        const double* row = cost + src * n;
        for (npy_intp j = 0; j < n; j++) {
            seen[j] = 0;
            dist[j] = row[j] - us - v[j];
            pred[j] = src;
        }
        npy_intp sink = -1;
        double mind = 0.0;
        for (npy_intp step = 0; step < n; step++) {
            double best = INF;
            npy_intp jmin = -1;
            for (npy_intp j = 0; j < n; j++) {
                if (!seen[j] && dist[j] < best) { best = dist[j]; jmin = j; }
            }
            seen[jmin] = 1;
            npy_intp rmatch = colsol[jmin];
            if (rmatch < 0) { sink = jmin; mind = best; break; }
            double base = best - u[rmatch];
            const double* rcost = cost + rmatch * n;
            for (npy_intp j = 0; j < n; j++) {
                if (!seen[j]) {
                    double nd = base + rcost[j] - v[j];
                    if (nd < dist[j]) { dist[j] = nd; pred[j] = rmatch; }
                }
            }
        }
        u[src] += mind;
        for (npy_intp j = 0; j < n; j++) {
            if (seen[j]) {
                double dlt = dist[j] - mind;
                v[j] += dlt;
                npy_intp r = colsol[j];
                if (r >= 0) u[r] -= dlt;
            }
        }
        npy_intp j = sink;
        while (1) {
            npy_intp r = pred[j];
            npy_intp pj = rowsol[r];
            rowsol[r] = j;
            colsol[j] = r;
            if (r == src) break;
            j = pj;
        }
    }
    free(dist); free(pred); free(seen);
}

static PyObject* solve_assign(PyObject* self, PyObject* args) {
    PyObject* cost_obj;
    int k = 40;
    if (!PyArg_ParseTuple(args, "O|i", &cost_obj, &k)) return NULL;
    PyArrayObject* cost_arr = (PyArrayObject*)PyArray_FROM_OTF(cost_obj, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY);
    if (!cost_arr) return NULL;
    if (PyArray_NDIM(cost_arr) != 2) {
        Py_DECREF(cost_arr);
        PyErr_SetString(PyExc_ValueError, "cost must be 2d");
        return NULL;
    }
    npy_intp n = PyArray_DIM(cost_arr, 0);
    npy_intp m = PyArray_DIM(cost_arr, 1);
    if (n != m) {
        Py_DECREF(cost_arr);
        PyErr_SetString(PyExc_ValueError, "cost must be square");
        return NULL;
    }
    if (k > n) k = (int)n;
    if (k < 1) k = 1;
    const double* cost = (const double*)PyArray_DATA(cost_arr);

    double* u = (double*)calloc(n, sizeof(double));
    double* v = (double*)malloc(n * sizeof(double));
    npy_intp* rowsol = (npy_intp*)malloc(n * sizeof(npy_intp));
    npy_intp* colsol = (npy_intp*)malloc(n * sizeof(npy_intp));
    npy_intp* free_rows = (npy_intp*)malloc(n * sizeof(npy_intp));
    npy_intp* cand = (npy_intp*)malloc(n * k * sizeof(npy_intp));
    double* kval = (double*)malloc(k * sizeof(double));
    npy_intp* kidx = (npy_intp*)malloc(k * sizeof(npy_intp));
    for (npy_intp i = 0; i < n; i++) { rowsol[i] = -1; colsol[i] = -1; }

    /* kNN */
    for (npy_intp i = 0; i < n; i++) {
        knn_one(cost + i * n, n, k, kidx, kval);
        memcpy(cand + i * k, kidx, k * sizeof(npy_intp));
    }

    /* column reduction */
    for (npy_intp j = n - 1; j >= 0; j--) {
        double best = cost[j];
        npy_intp bi = 0;
        for (npy_intp i = 1; i < n; i++) {
            double cij = cost[i * n + j];
            if (cij < best) { best = cij; bi = i; }
        }
        v[j] = best;
        if (rowsol[bi] < 0) {
            rowsol[bi] = j;
            colsol[j] = bi;
        }
    }

    npy_intp nf = 0;
    const double INF = 1e100;
    for (npy_intp i = 0; i < n; i++) {
        if (rowsol[i] >= 0) {
            npy_intp j = rowsol[i];
            u[i] = cost[i * n + j] - v[j];
            continue;
        }
        double mn = INF;
        npy_intp j1 = cand[i * k];
        const double* row = cost + i * n;
        const npy_intp* ci = cand + i * k;
        for (int t = 0; t < k; t++) {
            npy_intp j = ci[t];
            double red = row[j] - v[j];
            if (red < mn) { mn = red; j1 = j; }
        }
        u[i] = mn;
        if (colsol[j1] < 0) {
            rowsol[i] = j1;
            colsol[j1] = i;
        } else {
            free_rows[nf++] = i;
        }
    }

    int ok = ssp_cand(cost, n, k, cand, u, v, rowsol, colsol, free_rows, nf);
    if (!ok) {
        /* reset and do full */
        for (npy_intp i = 0; i < n; i++) { rowsol[i] = -1; colsol[i] = -1; u[i] = 0; }
        for (npy_intp j = n - 1; j >= 0; j--) {
            double best = cost[j];
            npy_intp bi = 0;
            for (npy_intp i = 1; i < n; i++) {
                double cij = cost[i * n + j];
                if (cij < best) { best = cij; bi = i; }
            }
            v[j] = best;
            if (rowsol[bi] < 0) { rowsol[bi] = j; colsol[j] = bi; }
        }
        nf = 0;
        for (npy_intp i = 0; i < n; i++) {
            if (rowsol[i] >= 0) {
                u[i] = cost[i * n + rowsol[i]] - v[rowsol[i]];
                continue;
            }
            double mn = INF;
            npy_intp j1 = 0;
            const double* row = cost + i * n;
            for (npy_intp j = 0; j < n; j++) {
                double red = row[j] - v[j];
                if (red < mn) { mn = red; j1 = j; }
            }
            u[i] = mn;
            if (colsol[j1] < 0) { rowsol[i] = j1; colsol[j1] = i; }
            else free_rows[nf++] = i;
        }
        ssp_full(cost, n, u, v, rowsol, colsol, free_rows, nf);
    }

    npy_intp dims[1] = {n};
    PyObject* out = PyArray_SimpleNew(1, dims, NPY_INT64);
    npy_intp* odata = (npy_intp*)PyArray_DATA((PyArrayObject*)out);
    memcpy(odata, rowsol, n * sizeof(npy_intp));

    free(u); free(v); free(rowsol); free(colsol); free(free_rows);
    free(cand); free(kval); free(kidx);
    Py_DECREF(cost_arr);
    return out;
}

static PyMethodDef methods[] = {
    {"solve_assign", solve_assign, METH_VARARGS, "assignment"},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "lapjv", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_lapjv(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
