#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <stdlib.h>
#include <string.h>

/*
 * Exact min-cost assignment (Jonker-Volgenant style):
 *   column reduction, then successive shortest paths with a binary heap
 *   over a k-NN candidate graph. Falls back to dense SSP if needed.
 * Returns int64 row->col.
 */

static void knn_one(const double* row, npy_intp n, int k, npy_intp* idx, double* val) {
    for (int t = 0; t < k; t++) {
        idx[t] = t;
        val[t] = row[t];
    }
    int tmax = 0;
    double mv = val[0];
    for (int t = 1; t < k; t++) if (val[t] > mv) { mv = val[t]; tmax = t; }
    for (npy_intp j = k; j < n; j++) {
        double rj = row[j];
        if (rj < mv) {
            idx[tmax] = j;
            val[tmax] = rj;
            tmax = 0; mv = val[0];
            for (int t = 1; t < k; t++) if (val[t] > mv) { mv = val[t]; tmax = t; }
        }
    }
}

static inline void heap_push(npy_intp* hj, double* hd, npy_intp* hs, npy_intp j, double d) {
    npy_intp c = (*hs)++;
    hj[c] = j; hd[c] = d;
    while (c > 0) {
        npy_intp p = (c - 1) >> 1;
        if (hd[p] <= hd[c]) break;
        double td = hd[p]; hd[p] = hd[c]; hd[c] = td;
        npy_intp tj = hj[p]; hj[p] = hj[c]; hj[c] = tj;
        c = p;
    }
}

static inline void heap_pop(npy_intp* hj, double* hd, npy_intp* hs, npy_intp* j, double* d) {
    *j = hj[0]; *d = hd[0];
    npy_intp n = --(*hs);
    if (n > 0) {
        hj[0] = hj[n]; hd[0] = hd[n];
        npy_intp c = 0;
        while (1) {
            npy_intp l = c * 2 + 1;
            if (l >= n) break;
            npy_intp r = l + 1;
            npy_intp m = l;
            if (r < n && hd[r] < hd[l]) m = r;
            if (hd[c] <= hd[m]) break;
            double td = hd[c]; hd[c] = hd[m]; hd[m] = td;
            npy_intp tj = hj[c]; hj[c] = hj[m]; hj[m] = tj;
            c = m;
        }
    }
}

static int ssp_cand(
    const double* cost, npy_intp n, int k, const npy_intp* cand,
    double* u, double* v, npy_intp* rowsol, npy_intp* colsol,
    npy_intp* free_rows, npy_intp nf
) {
    const double INF = 1e300;
    npy_intp cap = n * (npy_intp)k + 8;
    double* dist = (double*)malloc(n * sizeof(double));
    npy_intp* pred = (npy_intp*)malloc(n * sizeof(npy_intp));
    npy_intp* stamp = (npy_intp*)calloc(n, sizeof(npy_intp));
    npy_intp* seen = (npy_intp*)calloc(n, sizeof(npy_intp));
    npy_intp* hj = (npy_intp*)malloc(cap * sizeof(npy_intp));
    double* hd = (double*)malloc(cap * sizeof(double));
    if (!dist || !pred || !stamp || !seen || !hj || !hd) return 0;
    npy_intp cur = 1;

    for (npy_intp t = 0; t < nf; t++) {
        npy_intp src = free_rows[t];
        cur++;
        npy_intp hs = 0;
        double us = u[src];
        const double* row = cost + src * n;
        const npy_intp* ci = cand + (npy_intp)src * k;
        for (int tt = 0; tt < k; tt++) {
            npy_intp j = ci[tt];
            double d = row[j] - us - v[j];
            if (stamp[j] != cur || d < dist[j]) {
                dist[j] = d;
                pred[j] = src;
                stamp[j] = cur;
                heap_push(hj, hd, &hs, j, d);
            }
        }
        npy_intp sink = -1;
        double mind = 0.0;
        while (hs > 0) {
            npy_intp jmin; double dmin;
            heap_pop(hj, hd, &hs, &jmin, &dmin);
            if (stamp[jmin] != cur || seen[jmin] == cur) continue;
            if (dmin > dist[jmin]) continue;
            seen[jmin] = cur;
            npy_intp rmatch = colsol[jmin];
            if (rmatch < 0) { sink = jmin; mind = dmin; break; }
            double base = dmin - u[rmatch];
            const double* rcost = cost + rmatch * n;
            const npy_intp* crow = cand + rmatch * k;
            for (int tt = 0; tt < k; tt++) {
                npy_intp j = crow[tt];
                if (seen[j] == cur) continue;
                double nd = base + rcost[j] - v[j];
                if (stamp[j] != cur || nd < dist[j]) {
                    dist[j] = nd;
                    pred[j] = rmatch;
                    stamp[j] = cur;
                    heap_push(hj, hd, &hs, j, nd);
                }
            }
        }
        if (sink < 0) {
            free(dist); free(pred); free(stamp); free(seen); free(hj); free(hd);
            return 0;
        }
        u[src] += mind;
        for (npy_intp j = 0; j < n; j++) {
            if (seen[j] == cur) {
                double dlt = dist[j] - mind;
                v[j] += dlt;
                npy_intp r = colsol[j];
                if (r >= 0) u[r] -= dlt;
            }
        }
        npy_intp j = sink;
        while (1) {
            npy_intp r = pred[j];
            npy_intp pj = rowsol[r];
            rowsol[r] = j;
            colsol[j] = r;
            if (r == src) break;
            j = pj;
        }
    }
    free(dist); free(pred); free(stamp); free(seen); free(hj); free(hd);
    return 1;
}

static void ssp_full(
    const double* cost, npy_intp n, double* u, double* v,
    npy_intp* rowsol, npy_intp* colsol, npy_intp* free_rows, npy_intp nf
) {
    const double INF = 1e300;
    double* dist = (double*)malloc(n * sizeof(double));
    npy_intp* pred = (npy_intp*)malloc(n * sizeof(npy_intp));
    unsigned char* seen = (unsigned char*)malloc(n);
    for (npy_intp t = 0; t < nf; t++) {
        npy_intp src = free_rows[t];
        double us = u[src];
        const double* row = cost + src * n;
        for (npy_intp j = 0; j < n; j++) {
            seen[j] = 0;
            dist[j] = row[j] - us - v[j];
            pred[j] = src;
        }
        npy_intp sink = -1;
        double mind = 0;
        for (npy_intp step = 0; step < n; step++) {
            double best = INF;
            npy_intp jmin = 0;
            for (npy_intp j = 0; j < n; j++) if (!seen[j] && dist[j] < best) { best = dist[j]; jmin = j; }
            seen[jmin] = 1;
            npy_intp rmatch = colsol[jmin];
            if (rmatch < 0) { sink = jmin; mind = best; break; }
            double base = best - u[rmatch];
            const double* rcost = cost + rmatch * n;
            for (npy_intp j = 0; j < n; j++) if (!seen[j]) {
                double nd = base + rcost[j] - v[j];
                if (nd < dist[j]) { dist[j] = nd; pred[j] = rmatch; }
            }
        }
        u[src] += mind;
        for (npy_intp j = 0; j < n; j++) if (seen[j]) {
            double dlt = dist[j] - mind;
            v[j] += dlt;
            npy_intp r = colsol[j];
            if (r >= 0) u[r] -= dlt;
        }
        npy_intp j = sink;
        while (1) {
            npy_intp r = pred[j];
            npy_intp pj = rowsol[r];
            rowsol[r] = j; colsol[j] = r;
            if (r == src) break;
            j = pj;
        }
    }
    free(dist); free(pred); free(seen);
}

static PyObject* solve_assign(PyObject* self, PyObject* args) {
    PyObject* cost_obj;
    int k = 48;
    if (!PyArg_ParseTuple(args, "O|i", &cost_obj, &k)) return NULL;
    PyArrayObject* cost_arr = (PyArrayObject*)PyArray_FROM_OTF(cost_obj, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY);
    if (!cost_arr) return NULL;
    npy_intp n = PyArray_DIM(cost_arr, 0);
    npy_intp m = PyArray_DIM(cost_arr, 1);
    if (PyArray_NDIM(cost_arr) != 2 || n != m) {
        Py_DECREF(cost_arr);
        PyErr_SetString(PyExc_ValueError, "square cost required");
        return NULL;
    }
    if (k > n) k = (int)n;
    const double* cost = (const double*)PyArray_DATA(cost_arr);

    double* u = (double*)calloc(n, sizeof(double));
    double* v = (double*)malloc(n * sizeof(double));
    npy_intp* rowsol = (npy_intp*)malloc(n * sizeof(npy_intp));
    npy_intp* colsol = (npy_intp*)malloc(n * sizeof(npy_intp));
    npy_intp* free_rows = (npy_intp*)malloc(n * sizeof(npy_intp));
    npy_intp* cand = (npy_intp*)malloc((npy_intp)n * k * sizeof(npy_intp));
    double* kval = (double*)malloc(k * sizeof(double));
    npy_intp* kidx = (npy_intp*)malloc(k * sizeof(npy_intp));
    for (npy_intp i = 0; i < n; i++) { rowsol[i] = -1; colsol[i] = -1; }

    for (npy_intp i = 0; i < n; i++) {
        knn_one(cost + i * n, n, k, kidx, kval);
        memcpy(cand + i * k, kidx, k * sizeof(npy_intp));
    }

    for (npy_intp j = n - 1; j >= 0; --j) {
        double best = cost[j];
        npy_intp bi = 0;
        for (npy_intp i = 1; i < n; i++) {
            double cij = cost[i * n + j];
            if (cij < best) { best = cij; bi = i; }
        }
        v[j] = best;
        if (rowsol[bi] < 0) { rowsol[bi] = j; colsol[j] = bi; }
    }

    const double INF = 1e300;
    npy_intp nf = 0;
    for (npy_intp i = 0; i < n; i++) {
        if (rowsol[i] >= 0) {
            u[i] = cost[i * n + rowsol[i]] - v[rowsol[i]];
            continue;
        }
        double mn = INF;
        npy_intp j1 = cand[i * k];
        const double* row = cost + i * n;
        const npy_intp* ci = cand + i * k;
        for (int t = 0; t < k; t++) {
            npy_intp j = ci[t];
            double red = row[j] - v[j];
            if (red < mn) { mn = red; j1 = j; }
        }
        u[i] = mn;
        if (colsol[j1] < 0) { rowsol[i] = j1; colsol[j1] = i; }
        else free_rows[nf++] = i;
    }

    int ok = ssp_cand(cost, n, k, cand, u, v, rowsol, colsol, free_rows, nf);
    if (!ok) {
        for (npy_intp i = 0; i < n; i++) { rowsol[i] = -1; colsol[i] = -1; u[i] = 0; }
        for (npy_intp j = n - 1; j >= 0; --j) {
            double best = cost[j]; npy_intp bi = 0;
            for (npy_intp i = 1; i < n; i++) {
                double cij = cost[i * n + j];
                if (cij < best) { best = cij; bi = i; }
            }
            v[j] = best;
            if (rowsol[bi] < 0) { rowsol[bi] = j; colsol[j] = bi; }
        }
        nf = 0;
        for (npy_intp i = 0; i < n; i++) {
            if (rowsol[i] >= 0) { u[i] = cost[i * n + rowsol[i]] - v[rowsol[i]]; continue; }
            double mn = INF; npy_intp j1 = 0;
            const double* row = cost + i * n;
            for (npy_intp j = 0; j < n; j++) {
                double red = row[j] - v[j];
                if (red < mn) { mn = red; j1 = j; }
            }
            u[i] = mn;
            if (colsol[j1] < 0) { rowsol[i] = j1; colsol[j1] = i; }
            else free_rows[nf++] = i;
        }
        ssp_full(cost, n, u, v, rowsol, colsol, free_rows, nf);
    }

    npy_intp dims[1] = {n};
    PyObject* out = PyArray_SimpleNew(1, dims, NPY_INT64);
    memcpy(PyArray_DATA((PyArrayObject*)out), rowsol, n * sizeof(npy_intp));
    free(u); free(v); free(rowsol); free(colsol); free(free_rows);
    free(cand); free(kval); free(kidx);
    Py_DECREF(cost_arr);
    return out;
}

static PyMethodDef methods[] = {
    {"solve_assign", solve_assign, METH_VARARGS, ""},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "lapjv", NULL, -1, methods};
PyMODINIT_FUNC PyInit_lapjv(void) { import_array(); return PyModule_Create(&moduledef); }
