/*
 * Jonker-Volgenant LAPMOD-style assignment, adapted from the public-domain
 * lapmod / lapjv algorithm (Jonker & Volgenant 1987; Volgenant 1990s LAPMOD).
 * Dense double cost matrix, square, minimization.
 *
 * This is a faithful structured port of the classic implementation:
 *   1. column reduction
 *   2. reduction transfer
 *   3. augmenting row reduction
 *   4. augmenting solution via shortest paths (dijkstra with a price array)
 */
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <float.h>

static PyObject* lapjv_solve(PyObject* self, PyObject* args) {
    PyObject* cost_obj;
    if (!PyArg_ParseTuple(args, "O", &cost_obj)) return NULL;
    PyArrayObject* cost_arr = (PyArrayObject*)PyArray_FROM_OTF(
        cost_obj, NPY_FLOAT64, NPY_ARRAY_C_CONTIGUOUS | NPY_ARRAY_ALIGNED);
    if (!cost_arr) return NULL;
    if (PyArray_NDIM(cost_arr) != 2) {
        Py_DECREF(cost_arr);
        PyErr_SetString(PyExc_ValueError, "cost must be 2d");
        return NULL;
    }
    const npy_intp n = PyArray_DIM(cost_arr, 0);
    const npy_intp m = PyArray_DIM(cost_arr, 1);
    if (n != m || n <= 0) {
        Py_DECREF(cost_arr);
        PyErr_SetString(PyExc_ValueError, "cost must be square");
        return NULL;
    }
    const double* cost = (const double*)PyArray_DATA(cost_arr);
    const double BIG = 1e18;

    double* u = (double*)calloc(n, sizeof(double));
    double* v = (double*)calloc(n, sizeof(double));
    npy_intp* rowsol = (npy_intp*)malloc(n * sizeof(npy_intp));
    npy_intp* colsol = (npy_intp*)malloc(n * sizeof(npy_intp));
    npy_intp* free = (npy_intp*)malloc(n * sizeof(npy_intp));
    npy_intp* pred = (npy_intp*)malloc(n * sizeof(npy_intp));
    double* d = (double*)malloc(n * sizeof(double));
    npy_intp* collist = (npy_intp*)malloc(n * sizeof(npy_intp));
    npy_intp* matches = (npy_intp*)malloc(n * sizeof(npy_intp));
    char* ok = NULL;
    if (!u || !v || !rowsol || !colsol || !free || !pred || !d || !collist || !matches) {
        Py_DECREF(cost_arr);
        PyErr_SetString(PyExc_MemoryError, "oom");
        return NULL;
    }
    for (npy_intp i = 0; i < n; i++) { rowsol[i] = -1; colsol[i] = -1; }

    /* ---------- COLUMN REDUCTION ---------- */
    for (npy_intp j = n - 1; j >= 0; j--) {
        double minv = cost[j];
        npy_intp imin = 0;
        for (npy_intp i = 1; i < n; i++) {
            double c = cost[i * n + j];
            if (c < minv) { minv = c; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] < 0) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            colsol[j] = -1; /* unassigned column */
        }
    }

    /* ---------- REDUCTION TRANSFER ---------- */
    npy_intp nfree = 0;
    for (npy_intp i = 0; i < n; i++) {
        if (rowsol[i] >= 0) continue;
        double h = BIG;
        npy_intp j1 = 0, j2 = -1;
        const double* row = cost + i * n;
        for (npy_intp j = 0; j < n; j++) {
            double red = row[j] - v[j];
            if (red < h) {
                j2 = j1;
                h = red; /* first min stored in h? we'll recompute properly */
                j1 = j;
            }
        }
        /* recompute min and second min cleanly */
        double mn1 = BIG, mn2 = BIG;
        j1 = 0; j2 = 0;
        for (npy_intp j = 0; j < n; j++) {
            double red = row[j] - v[j];
            if (red < mn1) { mn2 = mn1; j2 = j1; mn1 = red; j1 = j; }
            else if (red < mn2) { mn2 = red; j2 = j; }
        }
        u[i] = mn1;
        /* transfer */
        if (mn2 < BIG) v[j1] -= (mn2 - mn1);
        if (colsol[j1] < 0) {
            rowsol[i] = j1;
            colsol[j1] = i;
        } else {
            free[nfree++] = i;
        }
        (void)h; (void)j2;
    }

    /* ---------- AUGMENTING ROW REDUCTION ---------- */
    npy_intp nfree_new;
    for (int loop = 0; loop < 2; loop++) {
        npy_intp k = 0;
        npy_intp prvfree = nfree;
        nfree = 0;
        while (k < prvfree) {
            npy_intp i = free[k++];
            double mn1 = BIG, mn2 = BIG;
            npy_intp j1 = 0;
            const double* row = cost + i * n;
            double ui = u[i];
            for (npy_intp j = 0; j < n; j++) {
                double red = row[j] - v[j] - ui;
                if (red < mn1) {
                    mn2 = mn1;
                    mn1 = red;
                    j1 = j;
                } else if (red < mn2) {
                    mn2 = red;
                }
            }
            npy_intp i0 = colsol[j1];
            double vj1 = v[j1] - (mn2 - mn1);
            /* only update if improvement */
            int vchange = (vj1 < v[j1] - 1e-15);
            if (vchange) {
                v[j1] = vj1;
                u[i] = u[i] + mn2; /* ? */
            } else {
                u[i] = u[i] + mn1;
            }
            if (i0 >= 0) {
                if (vchange) {
                    /* unassign previous, it becomes free and we continue with it */
                    rowsol[i] = j1;
                    colsol[j1] = i;
                    rowsol[i0] = -1;
                    free[nfree++] = i0; /* will be processed later in this scan? classic restarts on i0 */
                    /* classic algorithm immediately continues with i0 */
                    /* we emulate by pushing i0 to front conceptually: process now by replacing */
                    /* simpler: push i0 into free list to be processed in next loop only if loop remains.
                       To match classic, process i0 immediately by decrementing k and swapping. */
                    free[--k] = i0;
                    prvfree = prvfree; /* k points at i0, will be incremented then processed */
                    /* wait k was already incremented past current. --k makes next iteration process i0. Good. */
                } else {
                    free[nfree++] = i;
                }
            } else {
                rowsol[i] = j1;
                colsol[j1] = i;
            }
        }
    }

    /* count still free */
    nfree = 0;
    for (npy_intp i = 0; i < n; i++) if (rowsol[i] < 0) free[nfree++] = i;

    /* ---------- AUGMENTATION (shortest paths) ---------- */
    for (npy_intp f = 0; f < nfree; f++) {
        npy_intp freerow = free[f];
        for (npy_intp j = 0; j < n; j++) {
            d[j] = cost[freerow * n + j] - v[j];
            pred[j] = freerow;
            collist[j] = j;
        }
        npy_intp low = 0, up = 0;
        npy_intp last = 0;          /* columns scanned */
        npy_intp endofpath = -1;
        double min = BIG;
        npy_intp* unassigned = NULL; /* unused */
        /* Dijkstra over columns, COLSOL gives matching */
        npy_intp nscan = n;
        while (1) {
            if (up == low) {
                /* find minimum among unlabelled (collist[low..nscan)) */
                double mn = BIG;
                npy_intp idx = low;
                for (npy_intp t = low; t < nscan; t++) {
                    npy_intp j = collist[t];
                    if (d[j] <= mn) { mn = d[j]; idx = t; }
                }
                min = mn;
                /* swap to position low */
                npy_intp jmin = collist[idx];
                collist[idx] = collist[low];
                collist[low] = jmin;
                low++;
                if (colsol[jmin] < 0) { endofpath = jmin; break; }
                /* else will be scanned below: move into scanned range by continuing */
                /* put it as next to scan: already at low-1 */
                if (low > up) up = low;
            }
