/* Column reduction + reduction transfer + dense successive shortest paths.
   Minimization assignment. Returns int64 row->col. */

static PyObject* lap_solve(PyObject* self, PyObject* args) {
    PyObject* cost_obj;
    if (!PyArg_ParseTuple(args, "O", &cost_obj)) return NULL;
    PyArrayObject* arr = (PyArrayObject*)PyArray_FROM_OTF(
        cost_obj, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY);
    if (!arr) return NULL;
    if (PyArray_NDIM(arr) != 2 || PyArray_DIM(arr, 0) != PyArray_DIM(arr, 1)) {
        Py_DECREF(arr);
        PyErr_SetString(PyExc_ValueError, "square cost required");
        return NULL;
    }
    const npy_intp n = PyArray_DIM(arr, 0);
    const double* cost = (const double*)PyArray_DATA(arr);
    const double BIG = 1e300;

    double* u = (double*)calloc(n, sizeof(double));
    double* v = (double*)malloc(n * sizeof(double));
    npy_intp* rowsol = (npy_intp*)malloc(n * sizeof(npy_intp));
    npy_intp* colsol = (npy_intp*)malloc(n * sizeof(npy_intp));
    npy_intp* freelist = (npy_intp*)malloc(n * sizeof(npy_intp));
    double* dist = (double*)malloc(n * sizeof(double));
    npy_intp* pred = (npy_intp*)malloc(n * sizeof(npy_intp));
    unsigned char* seen = (unsigned char*)malloc(n);
    for (npy_intp i = 0; i < n; i++) { rowsol[i] = -1; colsol[i] = -1; }

    /* column reduction, reverse order (JV) */
    for (npy_intp j = n - 1; j >= 0; --j) {
        double best = cost[j];
        npy_intp bi = 0;
        for (npy_intp i = 1; i < n; i++) {
            double cij = cost[i * n + j];
            if (cij < best) { best = cij; bi = i; }
        }
        v[j] = best;
        if (rowsol[bi] < 0) {
            rowsol[bi] = j;
            colsol[j] = bi;
        }
    }

    /* reduction transfer + collect free rows */
    npy_intp nf = 0;
    for (npy_intp i = 0; i < n; i++) {
        if (rowsol[i] >= 0) {
            npy_intp j = rowsol[i];
            u[i] = cost[i * n + j] - v[j];
            continue;
        }
        const double* row = cost + i * n;
        double mn1 = BIG, mn2 = BIG;
        npy_intp j1 = 0;
        for (npy_intp j = 0; j < n; j++) {
            double red = row[j] - v[j];
            if (red < mn1) { mn2 = mn1; mn1 = red; j1 = j; }
            else if (red < mn2) { mn2 = red; }
        }
        /* transfer: lower dual of j1 so its reduced cost matches second best.
           This preserves feasibility of already matched rows because their
           matched reduced cost stays 0 only if we also adjust u. We only
           transfer when j1 is free, which cannot break a match. */
        u[i] = mn1;
        if (colsol[j1] < 0) {
            rowsol[i] = j1;
            colsol[j1] = i;
        } else {
            freelist[nf++] = i;
        }
    }

    /* successive shortest paths for free rows */
    for (npy_intp f = 0; f < nf; f++) {
        npy_intp src = freelist[f];
        double us = u[src];
        const double* row = cost + src * n;
        for (npy_intp j = 0; j < n; j++) {
            seen[j] = 0;
            dist[j] = row[j] - us - v[j];
            pred[j] = src;
        }
        npy_intp sink = -1;
        double mind = 0.0;
        for (npy_intp step = 0; step < n; step++) {
            double best = BIG;
            npy_intp jmin = 0;
            for (npy_intp j = 0; j < n; j++) {
                if (!seen[j] && dist[j] < best) { best = dist[j]; jmin = j; }
            }
            seen[jmin] = 1;
            npy_intp rmatch = colsol[jmin];
            if (rmatch < 0) { sink = jmin; mind = best; break; }
            double base = best - u[rmatch];
            const double* rcost = cost + rmatch * n;
            for (npy_intp j = 0; j < n; j++) {
                if (!seen[j]) {
                    double nd = base + rcost[j] - v[j];
                    if (nd < dist[j]) { dist[j] = nd; pred[j] = rmatch; }
                }
            }
        }
        u[src] += mind;
        for (npy_intp j = 0; j < n; j++) if (seen[j]) {
            double dlt = dist[j] - mind;
            v[j] += dlt;
            npy_intp r = colsol[j];
            if (r >= 0) u[r] -= dlt;
        }
        npy_intp j = sink;
        while (1) {
            npy_intp r = pred[j];
            npy_intp pj = rowsol[r];
            rowsol[r] = j;
            colsol[j] = r;
            if (r == src) break;
            j = pj;
        }
    }

    npy_intp dims[1] = {n};
    PyObject* out = PyArray_SimpleNew(1, dims, NPY_INT64);
    memcpy(PyArray_DATA((PyArrayObject*)out), rowsol, n * sizeof(npy_intp));

    free(u); free(v); free(rowsol); free(colsol); free(freelist);
    free(dist); free(pred); free(seen);
    Py_DECREF(arr);
    return out;
}

