#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <stdlib.h>
#include <string.h>

/* Exact assignment via column reduction + SSP on a k-NN candidate graph.
   Candidate edge costs are stored compactly so the search never touches the
   full matrix. Optimality is verified against all reduced costs; on failure
   the candidate set is grown and the search is repeated. */

static void col_reduce(const double* cost, npy_intp n, double* v, npy_intp* rowsol, npy_intp* colsol) {
    for (npy_intp j = 0; j < n; j++) {
        v[j] = 1e300;
        colsol[j] = -1;
    }
    for (npy_intp i = 0; i < n; i++) rowsol[i] = -1;
    const double* row = cost;
    for (npy_intp i = 0; i < n; i++, row += n) {
        for (npy_intp j = 0; j < n; j++) {
            double c = row[j];
            if (c < v[j]) {
                v[j] = c;
                colsol[j] = i; /* tentative cheapest row; assignment resolved below */
            }
        }
    }
    /* assign in reverse column order, matching JV / previous experiments */
    for (npy_intp j = 0; j < n; j++) colsol[j] = -1;
    for (npy_intp j = n - 1; j >= 0; --j) {
        double best = cost[j];
        npy_intp bi = 0;
        for (npy_intp i = 1; i < n; i++) {
            double c = cost[i * n + j];
            if (c < best) { best = c; bi = i; }
        }
        v[j] = best;
        if (rowsol[bi] < 0) {
            rowsol[bi] = j;
            colsol[j] = bi;
        }
    }
}

static void build_knn(const double* cost, npy_intp n, int k, npy_intp* cand, double* cc) {
    npy_intp* idx = (npy_intp*)malloc(k * sizeof(npy_intp));
    double* val = (double*)malloc(k * sizeof(double));
    for (npy_intp i = 0; i < n; i++) {
        const double* row = cost + i * n;
        for (int t = 0; t < k; t++) { idx[t] = t; val[t] = row[t]; }
        int tmax = 0; double mv = val[0];
        for (int t = 1; t < k; t++) if (val[t] > mv) { mv = val[t]; tmax = t; }
        for (npy_intp j = k; j < n; j++) {
            double rj = row[j];
            if (rj < mv) {
                idx[tmax] = j; val[tmax] = rj;
                tmax = 0; mv = val[0];
                for (int t = 1; t < k; t++) if (val[t] > mv) { mv = val[t]; tmax = t; }
            }
        }
        npy_intp* c = cand + i * k;
        double* e = cc + i * k;
        for (int t = 0; t < k; t++) { c[t] = idx[t]; e[t] = val[t]; }
    }
    free(idx); free(val);
}

/* SSP on candidate graph. Returns 1 if a full assignment is found. */
static int ssp(const npy_intp* cand, const double* cc, npy_intp n, int k,
               double* u, double* v, npy_intp* rowsol, npy_intp* colsol,
               npy_intp* freelist, npy_intp nf) {
    const double INF = 1e300;
    double* dist = (double*)malloc(n * sizeof(double));
    npy_intp* pred = (npy_intp*)malloc(n * sizeof(npy_intp));
    unsigned char* seen = (unsigned char*)malloc(n);
    unsigned char* in_act = (unsigned char*)calloc(n, 1);
    npy_intp* active = (npy_intp*)malloc(n * sizeof(npy_intp));
    if (!dist || !pred || !seen || !in_act || !active) return 0;

    for (npy_intp f = 0; f < nf; f++) {
        npy_intp src = freelist[f];
        for (npy_intp j = 0; j < n; j++) { dist[j] = INF; seen[j] = 0; }
        npy_intp na = 0;
        double us = u[src];
        const npy_intp* ci = cand + src * k;
        const double* ce = cc + src * k;
        for (int t = 0; t < k; t++) {
            npy_intp j = ci[t];
            double d = ce[t] - us - v[j];
            if (d < dist[j]) { dist[j] = d; pred[j] = src; }
            if (!in_act[j]) { in_act[j] = 1; active[na++] = j; }
        }
        npy_intp sink = -1;
        double mind = 0.0;
        while (na > 0) {
            double best = INF;
            npy_intp ia = 0;
            for (npy_intp a = 0; a < na; a++) {
                double dj = dist[active[a]];
                if (dj < best) { best = dj; ia = a; }
            }
            npy_intp jmin = active[ia];
            active[ia] = active[--na];
            in_act[jmin] = 0;
            seen[jmin] = 1;
            npy_intp rmatch = colsol[jmin];
            if (rmatch < 0) { sink = jmin; mind = best; break; }
            double base = best - u[rmatch];
            const npy_intp* crow = cand + rmatch * k;
            const double* ccost = cc + rmatch * k;
            for (int t = 0; t < k; t++) {
                npy_intp j = crow[t];
                if (seen[j]) continue;
                double nd = base + ccost[t] - v[j];
                if (nd < dist[j]) {
                    dist[j] = nd;
                    pred[j] = rmatch;
                    if (!in_act[j]) { in_act[j] = 1; active[na++] = j; }
                }
            }
        }
        for (npy_intp a = 0; a < na; a++) in_act[active[a]] = 0;
        if (sink < 0) {
            free(dist); free(pred); free(seen); free(in_act); free(active);
            return 0;
        }
        u[src] += mind;
        for (npy_intp j = 0; j < n; j++) if (seen[j]) {
            double dlt = dist[j] - mind;
            v[j] += dlt;
            npy_intp r = colsol[j];
            if (r >= 0) u[r] -= dlt;
        }
        npy_intp j = sink;
        while (1) {
            npy_intp r = pred[j];
            npy_intp pj = rowsol[r];
            rowsol[r] = j;
            colsol[j] = r;
            if (r == src) break;
            j = pj;
        }
    }
    free(dist); free(pred); free(seen); free(in_act); free(active);
    return 1;
}

/* Count reduced-cost violations outside the current dual. */
static npy_intp count_violations(const double* cost, npy_intp n, const double* u, const double* v, double tol) {
    npy_intp bad = 0;
    for (npy_intp i = 0; i < n; i++) {
        const double* row = cost + i * n;
        double ui = u[i];
        for (npy_intp j = 0; j < n; j++) {
            if (row[j] - ui - v[j] < -tol) bad++;
        }
    }
    return bad;
}

static int solve_k(const double* cost, npy_intp n, int k,
                   double* u, double* v, npy_intp* rowsol, npy_intp* colsol) {
    npy_intp* cand = (npy_intp*)malloc((npy_intp)n * k * sizeof(npy_intp));
    double* cc = (double*)malloc((npy_intp)n * k * sizeof(double));
    npy_intp* freelist = (npy_intp*)malloc(n * sizeof(npy_intp));
    build_knn(cost, n, k, cand, cc);
    col_reduce(cost, n, v, rowsol, colsol);
    npy_intp nf = 0;
    const double INF = 1e300;
    for (npy_intp i = 0; i < n; i++) {
        if (rowsol[i] >= 0) {
            u[i] = cost[i * n + rowsol[i]] - v[rowsol[i]];
            continue;
        }
        double mn = INF;
        npy_intp j1 = cand[i * k];
        const npy_intp* ci = cand + i * k;
        const double* ce = cc + i * k;
        for (int t = 0; t < k; t++) {
            double red = ce[t] - v[ci[t]];
            if (red < mn) { mn = red; j1 = ci[t]; }
        }
        u[i] = mn;
        if (colsol[j1] < 0) { rowsol[i] = j1; colsol[j1] = i; }
        else freelist[nf++] = i;
    }
    int ok = ssp(cand, cc, n, k, u, v, rowsol, colsol, freelist, nf);
    free(cand); free(cc); free(freelist);
    return ok;
}

static PyObject* solve_assign(PyObject* self, PyObject* args) {
    PyObject* cost_obj;
    if (!PyArg_ParseTuple(args, "O", &cost_obj)) return NULL;
    PyArrayObject* arr = (PyArrayObject*)PyArray_FROM_OTF(cost_obj, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY);
    if (!arr) return NULL;
    npy_intp n = PyArray_DIM(arr, 0);
    if (PyArray_NDIM(arr) != 2 || PyArray_DIM(arr, 1) != n) {
        Py_DECREF(arr);
        PyErr_SetString(PyExc_ValueError, "square");
        return NULL;
    }
    const double* cost = (const double*)PyArray_DATA(arr);
    double* u = (double*)calloc(n, sizeof(double));
    double* v = (double*)malloc(n * sizeof(double));
    npy_intp* rowsol = (npy_intp*)malloc(n * sizeof(npy_intp));
    npy_intp* colsol = (npy_intp*)malloc(n * sizeof(npy_intp));

    int ks[] = {32, 48, 80, (int)n};
    int solved = 0;
    for (int attempt = 0; attempt < 4; attempt++) {
        int k = ks[attempt];
        if (k > n) k = (int)n;
        int ok = solve_k(cost, n, k, u, v, rowsol, colsol);
        if (!ok) continue;
        if (k == n || count_violations(cost, n, u, v, 1e-8) == 0) { solved = 1; break; }
    }
    (void)solved;
    npy_intp dims[1] = {n};
    PyObject* out = PyArray_SimpleNew(1, dims, NPY_INT64);
    memcpy(PyArray_DATA((PyArrayObject*)out), rowsol, n * sizeof(npy_intp));
    free(u); free(v); free(rowsol); free(colsol);
    Py_DECREF(arr);
    return out;
}

static PyMethodDef methods[] = {{"solve_assign", solve_assign, METH_VARARGS, ""}, {NULL,NULL,0,NULL}};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "lapfast", NULL, -1, methods};
PyMODINIT_FUNC PyInit_lapfast(void) { import_array(); return PyModule_Create(&moduledef); }
