static PyObject* solve_assign(PyObject* self, PyObject* args) {
    PyObject* cost_obj;
    if (!PyArg_ParseTuple(args, "O", &cost_obj)) return NULL;
    PyArrayObject* arr = (PyArrayObject*)PyArray_FROM_OTF(
