    const double* row0 = cost;
    for (npy_intp j = 0; j < n; j++) { v[j] = row0[j]; argmin[j] = 0; }
    for (npy_intp i = 1; i < n; i++) {
        const double* row = cost + i * n;
        for (npy_intp j = 0; j < n; j++) {
            double c = row[j];
            if (c < v[j]) { v[j] = c; argmin[j] = i; }
        }
    }
    /* assign in reverse column order so a row that is min of several columns
       keeps the lowest-index column, matching the JV convention used by the
       reference network simplex closely enough for a feasible start. */
    for (npy_intp j = n - 1; j >= 0; --j) {
        npy_intp i = argmin[j];
        if (rowsol[i] < 0) {
            rowsol[i] = j;
            colsol[j] = i;
