            rowsol[r] = j;
            colsol[j] = r;
            if (r == src) break;
            j = pj;
        }
    }
    double tE = now_sec();

    if (DBG) {
        fprintf(stderr, "n=%ld colred %.4f transfer %.4f arr %.4f ssp %.4f total %.4f free %ld->%ld\n",
