#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

/* Exact assignment: row-wise column reduction, dual-feasible augmenting
   row reduction, then successive shortest paths on a k-NN candidate graph.
   If the candidate graph cannot complete the matching, fall back to dense SSP.
*/

static double now_sec(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

static void build_knn(const double* cost, npy_intp n, int k, npy_intp* cand, double* cc) {
    npy_intp* idx = (npy_intp*)malloc((size_t)k * sizeof(npy_intp));
    double* val = (double*)malloc((size_t)k * sizeof(double));
    for (npy_intp i = 0; i < n; i++) {
        const double* row = cost + i * n;
        for (int t = 0; t < k; t++) { idx[t] = t; val[t] = row[t]; }
        int tmax = 0; double mv = val[0];
        for (int t = 1; t < k; t++) if (val[t] > mv) { mv = val[t]; tmax = t; }
        for (npy_intp j = k; j < n; j++) {
            double rj = row[j];
            if (rj < mv) {
                idx[tmax] = j; val[tmax] = rj;
                tmax = 0; mv = val[0];
                for (int t = 1; t < k; t++) if (val[t] > mv) { mv = val[t]; tmax = t; }
            }
        }
        npy_intp* c = cand + i * k;
        double* e = cc + i * k;
        for (int t = 0; t < k; t++) { c[t] = idx[t]; e[t] = val[t]; }
    }
    free(idx); free(val);
}

static int ssp_cand(
    const npy_intp* cand, const double* cc, npy_intp n, int k,
    double* u, double* v, npy_intp* rowsol, npy_intp* colsol,
    const npy_intp* freelist, npy_intp nf
) {
    const double INF = 1e300;
    double* dist = (double*)malloc(n * sizeof(double));
    npy_intp* pred = (npy_intp*)malloc(n * sizeof(npy_intp));
    unsigned char* seen = (unsigned char*)malloc(n);
    unsigned char* in_act = (unsigned char*)calloc(n, 1);
    npy_intp* active = (npy_intp*)malloc(n * sizeof(npy_intp));
    /* snapshot so a failure can be rolled back */
    double* u0 = (double*)malloc(n * sizeof(double));
    double* v0 = (double*)malloc(n * sizeof(double));
    npy_intp* rs0 = (npy_intp*)malloc(n * sizeof(npy_intp));
    npy_intp* cs0 = (npy_intp*)malloc(n * sizeof(npy_intp));
    memcpy(u0, u, n * sizeof(double));
    memcpy(v0, v, n * sizeof(double));
    memcpy(rs0, rowsol, n * sizeof(npy_intp));
    memcpy(cs0, colsol, n * sizeof(npy_intp));
    int ok = 1;
    for (npy_intp f = 0; f < nf && ok; f++) {
        npy_intp src = freelist[f];
        for (npy_intp j = 0; j < n; j++) { dist[j] = INF; seen[j] = 0; }
        npy_intp na = 0;
        double us = u[src];
        const npy_intp* ci = cand + src * k;
        const double* ce = cc + src * k;
        for (int t = 0; t < k; t++) {
            npy_intp j = ci[t];
            double d = ce[t] - us - v[j];
            if (d < dist[j]) { dist[j] = d; pred[j] = src; }
            if (!in_act[j]) { in_act[j] = 1; active[na++] = j; }
        }
        npy_intp sink = -1;
        double mind = 0.0;
        while (na > 0) {
            double best = INF;
            npy_intp ia = 0;
            for (npy_intp a = 0; a < na; a++) {
                double dj = dist[active[a]];
                if (dj < best) { best = dj; ia = a; }
            }
            npy_intp jmin = active[ia];
            active[ia] = active[--na];
            in_act[jmin] = 0;
            seen[jmin] = 1;
            npy_intp rmatch = colsol[jmin];
            if (rmatch < 0) { sink = jmin; mind = best; break; }
            double base = best - u[rmatch];
            const npy_intp* crow = cand + rmatch * k;
            const double* ccost = cc + rmatch * k;
            for (int t = 0; t < k; t++) {
                npy_intp j = crow[t];
                if (seen[j]) continue;
                double nd = base + ccost[t] - v[j];
                if (nd < dist[j]) {
                    dist[j] = nd; pred[j] = rmatch;
                    if (!in_act[j]) { in_act[j] = 1; active[na++] = j; }
                }
            }
        }
        for (npy_intp a = 0; a < na; a++) in_act[active[a]] = 0;
        if (sink < 0) { ok = 0; break; }
        u[src] += mind;
        for (npy_intp j = 0; j < n; j++) if (seen[j]) {
            double dlt = dist[j] - mind;
            v[j] += dlt;
            npy_intp r = colsol[j];
            if (r >= 0) u[r] -= dlt;
        }
        npy_intp j = sink;
        while (1) {
            npy_intp r = pred[j];
            npy_intp pj = rowsol[r];
            rowsol[r] = j; colsol[j] = r;
            if (r == src) break;
            j = pj;
        }
    }
    if (!ok) {
        memcpy(u, u0, n * sizeof(double));
        memcpy(v, v0, n * sizeof(double));
        memcpy(rowsol, rs0, n * sizeof(npy_intp));
        memcpy(colsol, cs0, n * sizeof(npy_intp));
    }
    free(dist); free(pred); free(seen); free(in_act); free(active);
    free(u0); free(v0); free(rs0); free(cs0);
    return ok;
}

static void ssp_dense(
