            double dlt = dist[j] - mind;
            v[j] += dlt;
            npy_intp r = colsol[j];
            if (r >= 0) u[r] -= dlt;
        }
        npy_intp j = sink;
        while (1) {
            npy_intp r = pred[j];
            npy_intp pj = rowsol[r];
            rowsol[r] = j; colsol[j] = r;
            if (r == src) break;
            j = pj;
        }
    }
    free(dist); free(pred); free(seen);
}

static PyObject* solve_assign(PyObject* self, PyObject* args) {
    PyObject* cost_obj;
    int k = 48;
    if (!PyArg_ParseTuple(args, "O|i", &cost_obj, &k)) return NULL;
    PyArrayObject* arr = (PyArrayObject*)PyArray_FROM_OTF(
        cost_obj, NPY_FLOAT64, NPY_ARRAY_C_CONTIGUOUS | NPY_ARRAY_ALIGNED);
    if (!arr) return NULL;
    if (PyArray_NDIM(arr) != 2 || PyArray_DIM(arr, 0) != PyArray_DIM(arr, 1)) {
        Py_DECREF(arr);
        PyErr_SetString(PyExc_ValueError, "square C-contiguous cost required");
        return NULL;
    }
    const npy_intp n = PyArray_DIM(arr, 0);
    if (k > n) k = (int)n;
    const double* cost = (const double*)PyArray_DATA(arr);
    const double BIG = 1e300;
    const int DBG = getenv("LAP_DEBUG") && getenv("LAP_DEBUG")[0] == '1';
    double tA = now_sec();

    double* u = (double*)calloc(n, sizeof(double));
    double* v = (double*)malloc(n * sizeof(double));
    npy_intp* rowsol = (npy_intp*)malloc(n * sizeof(npy_intp));
    npy_intp* colsol = (npy_intp*)malloc(n * sizeof(npy_intp));
    npy_intp* argmin = (npy_intp*)malloc(n * sizeof(npy_intp));
    npy_intp* freelist = (npy_intp*)malloc(n * sizeof(npy_intp));
    npy_intp* cand = (npy_intp*)malloc((size_t)n * k * sizeof(npy_intp));
    double* cc = (double*)malloc((size_t)n * k * sizeof(double));
    for (npy_intp i = 0; i < n; i++) { rowsol[i] = -1; colsol[i] = -1; }

    build_knn(cost, n, k, cand, cc);
    double tK = now_sec();

    const double* row0 = cost;
    for (npy_intp j = 0; j < n; j++) { v[j] = row0[j]; argmin[j] = 0; }
    for (npy_intp i = 1; i < n; i++) {
        const double* row = cost + i * n;
        for (npy_intp j = 0; j < n; j++) {
            double c = row[j];
            if (c < v[j]) { v[j] = c; argmin[j] = i; }
        }
    }
    for (npy_intp j = n - 1; j >= 0; --j) {
        npy_intp i = argmin[j];
        if (rowsol[i] < 0) { rowsol[i] = j; colsol[j] = i; u[i] = 0.0; }
    }
    {
        unsigned char* uniq = (unsigned char*)malloc(n);
        memset(uniq, 1, n);
        for (npy_intp j = 0; j < n; j++) if (rowsol[argmin[j]] != j) uniq[argmin[j]] = 0;
        for (npy_intp i = 0; i < n; i++) {
            if (rowsol[i] < 0 || !uniq[i]) continue;
            npy_intp jm = rowsol[i];
            const double* row = cost + i * n;
            double mn = BIG;
            for (npy_intp j = 0; j < n; j++) if (j != jm) {
                double red = row[j] - v[j];
                if (red < mn) mn = red;
            }
            if (mn < BIG / 2 && mn > 0) { v[jm] -= mn; u[i] = mn; }
        }
        free(uniq);
    }
    double tC = now_sec();

    npy_intp nf = 0;
    for (npy_intp i = 0; i < n; i++) if (rowsol[i] < 0) freelist[nf++] = i;
    npy_intp nf0 = nf;
    for (int pass = 0; pass < 4 && nf > 0; pass++) {
        npy_intp new_nf = 0;
        for (npy_intp t = 0; t < nf; t++) {
            npy_intp i = freelist[t];
            int placed = 0;
            for (int guard = 0; guard < 8 && !placed; guard++) {
                const double* row = cost + i * n;
                double ui = u[i];
                double mn1 = BIG, mn2 = BIG;
                npy_intp j1 = 0;
                for (npy_intp j = 0; j < n; j++) {
                    double red = row[j] - ui - v[j];
                    if (red < mn1) { mn2 = mn1; mn1 = red; j1 = j; }
                    else if (red < mn2) mn2 = red;
                }
                npy_intp owner = colsol[j1];
                if (owner < 0) {
                    u[i] += mn1;
                    rowsol[i] = j1; colsol[j1] = i;
                    placed = 1;
                    break;
                }
                double delta = mn2 - mn1;
                if (!(delta > 1e-15) || mn2 >= BIG / 2) break;
                v[j1] -= delta;
                u[owner] -= delta;
                u[i] = cost[i * n + j1] - v[j1];
                rowsol[owner] = -1;
                rowsol[i] = j1;
                colsol[j1] = i;
                i = owner;
            }
            if (!placed) freelist[new_nf++] = i;
        }
        nf = new_nf;
    }
    double tD = now_sec();
    npy_intp nf1 = nf;

    int used_cand = 0;
    if (nf > 0) {
        used_cand = ssp_cand(cand, cc, n, k, u, v, rowsol, colsol, freelist, nf);
        if (!used_cand) ssp_dense(cost, n, u, v, rowsol, colsol, freelist, nf);
    }
    double tE = now_sec();
    if (DBG) {
        fprintf(stderr, "n=%ld k=%d knn %.4f init %.4f arr %.4f ssp %.4f total %.4f free %ld->%ld cand_ok %d\n",
                (long)n, k, tK-tA, tC-tK, tD-tC, tE-tD, tE-tA, (long)nf0, (long)nf1, used_cand);
    }

    npy_intp dims[1] = {n};
    PyObject* out = PyArray_SimpleNew(1, dims, NPY_INT64);
    memcpy(PyArray_DATA((PyArrayObject*)out), rowsol, n * sizeof(npy_intp));
    free(u); free(v); free(rowsol); free(colsol); free(argmin);
    free(freelist); free(cand); free(cc);
    Py_DECREF(arr);
    return out;
}

static PyMethodDef methods[] = {{"solve_assign", solve_assign, METH_VARARGS, ""}, {NULL,NULL,0,NULL}};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "lapfast", NULL, -1, methods};
PyMODINIT_FUNC PyInit_lapfast(void) { import_array(); return PyModule_Create(&moduledef); }
EOF
PYINC=$(python3 -c "import sysconfig; print(sysconfig.get_paths()['include'])")
NPINC=$(python3 -c "import numpy; print(numpy.get_include())")
clang -O3 -ffast-math -march=native -shared -fPIC -undefined dynamic_lookup -I"$PYINC" -I"$NPINC" lapfast.c -o lapfast.so
LAP_DEBUG=1 python3 - << 'EOF'
import time, numpy as np, lapfast, ot
from ot.lp.emd_wrap import emd_c

def trial(n, k, seed):
    np.random.seed(seed)
    a = np.full(n, 1.0/n)
    M = np.ascontiguousarray(ot.dist(np.random.rand(n,2), np.random.rand(n,2)))
    t0 = time.perf_counter(); cols = lapfast.solve_assign(M, k); t = time.perf_counter()-t0
    t0 = time.perf_counter(); G, cost, u, v, rc = emd_c(a, a, M, 100000, 1, None, None); tr = time.perf_counter()-t0
    ref = np.argmax(G, 1)
    print(f"k={k} n={n} seed={seed} sol {t:.4f} ref {tr:.4f} speed {tr/t:.1f} match {np.array_equal(cols, ref)} cd {M[np.arange(n), cols].sum()/n - cost:.3e}")

print("small", lapfast.solve_assign(np.ascontiguousarray(np.random.rand(12,12)), 6)[:4])
for k in [24, 40, 64]:
    for s in range(3):
        trial(600, k, s+1)
EOF"}
